package com.nivor.analytics;
import com.nivor.analytics.AnalyticsDtos.*;import com.nivor.finance.FinanceDtos.Summary;import com.nivor.finance.FinanceService;import com.nivor.focus.*;import com.nivor.goal.*;import com.nivor.habit.*;import com.nivor.health.*;import com.nivor.journal.*;import com.nivor.project.*;import com.nivor.task.*;import com.nivor.user.UserService;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)public class AnalyticsService{private final UserService users;private final TaskRepository tasks;private final HabitRepository habits;private final HabitLogRepository logs;private final GoalRepository goals;private final ProjectRepository projects;private final JournalEntryRepository journal;private final FocusSessionRepository focus;private final FinanceService finance;private final HealthRecordService health;public AnalyticsService(UserService u,TaskRepository t,HabitRepository h,HabitLogRepository l,GoalRepository g,ProjectRepository p,JournalEntryRepository j,FocusSessionRepository f,FinanceService fi,HealthRecordService he){users=u;tasks=t;habits=h;logs=l;goals=g;projects=p;journal=j;focus=f;finance=fi;health=he;}
 private LocalDate[] range(LocalDate from,LocalDate to){LocalDate end=to==null?LocalDate.now():to,start=from==null?end.minusDays(29):from;if(end.isBefore(start)||ChronoUnit.DAYS.between(start,end)>365)throw new IllegalArgumentException("Analytics range must be between 1 and 366 days");return new LocalDate[]{start,end};}
 public Overview overview(String email,LocalDate from,LocalDate to){LocalDate[] r=range(from,to);long uid=users.getByEmail(email).getId();List<Task> ts=tasks.findAllByUser_IdOrderByDueDateAscDueTimeAsc(uid);long relevant=ts.stream().filter(t->t.getCreatedAt()!=null&&!t.getCreatedAt().toLocalDate().isAfter(r[1])).count();long done=ts.stream().filter(t->t.getCompletedAt()!=null&&!t.getCompletedAt().toLocalDate().isBefore(r[0])&&!t.getCompletedAt().toLocalDate().isAfter(r[1])).count();double rate=relevant==0?0:(double)done/relevant;HabitOverview h=habit(email,r[0],r[1]);GoalOverview g=goal(email);List<Project> ps=projects.findAllByUser_IdOrderByDeadlineAsc(uid);int pp=ps.isEmpty()?0:(int)Math.round(ps.stream().mapToInt(Project::getProgress).average().orElse(0));long fsecs=focus(email,r[0],r[1]).focusSeconds();long jcount=journal.findAllByUser_IdAndEntryDateBetweenOrderByEntryDateDesc(uid,r[0],r[1]).size();Summary s=finance.summary(email);int score=(int)Math.round(40*Math.min(rate,1)+30*h.consistency()+20*Math.min(fsecs/36000.0,1)+10*g.averageProgress()/100.0);return new Overview(r[0],r[1],done,relevant,rate,h.consistency(),g.averageProgress(),pp,jcount,fsecs,s.income(),s.expenses(),s.netSavings(),score,"40% task completion + 30% habit consistency + 20% focus time (capped at 10h) + 10% active-goal progress. A descriptive personal indicator, not a scientific measurement.");}
 public FocusOverview focus(String email,LocalDate from,LocalDate to){LocalDate[] r=range(from,to);long uid=users.getByEmail(email).getId();List<FocusSession> xs=focus.findAllByUser_IdOrderByStartedAtDesc(uid).stream().filter(x->x.getStatus()==FocusStatus.COMPLETED&&x.getStartedAt()!=null&&!x.getStartedAt().toLocalDate().isBefore(r[0])&&!x.getStartedAt().toLocalDate().isAfter(r[1])).toList();Map<LocalDate,List<FocusSession>> by=xs.stream().collect(java.util.stream.Collectors.groupingBy(x->x.getStartedAt().toLocalDate()));List<ProductivityPoint> daily=new ArrayList<>();for(LocalDate d=r[0];!d.isAfter(r[1]);d=d.plusDays(1)){List<FocusSession> day=by.getOrDefault(d,List.of());daily.add(new ProductivityPoint(d,0,day.stream().mapToLong(FocusSession::getDurationSeconds).sum()));}return new FocusOverview(xs.size(),xs.stream().mapToLong(FocusSession::getDurationSeconds).sum(),daily);}
 public HabitOverview habit(String email,LocalDate from,LocalDate to){LocalDate[] r=range(from,to);long uid=users.getByEmail(email).getId();List<Habit> active=habits.findAllByUser_IdOrderByCreatedAtAsc(uid).stream().filter(Habit::isActive).toList();long completions=active.stream().mapToLong(x->logs.countByHabit_IdAndCompletedTrueAndDateBetween(x.getId(),r[0],r[1])).sum();long opportunities=(long)active.size()*(ChronoUnit.DAYS.between(r[0],r[1])+1);return new HabitOverview(active.size(),completions,opportunities,opportunities==0?0:(double)completions/opportunities);}
 public GoalOverview goal(String email){List<Goal> active=goals.findAllByUser_IdOrderByDeadlineAsc(users.getByEmail(email).getId()).stream().filter(g->g.getStatus()==GoalStatus.ACTIVE).toList();long completed=goals.findAllByUser_IdOrderByDeadlineAsc(users.getByEmail(email).getId()).stream().filter(g->g.getStatus()==GoalStatus.COMPLETED).count();return new GoalOverview(active.size(),active.isEmpty()?0:(int)Math.round(active.stream().mapToInt(Goal::getProgress).average().orElse(0)),(int)completed);}
}
